async function runTriage(rawMessage) {
  try {
    const ai = getGeminiClient();
    if (!ai) throw new Error("Gemini API key no configurada");
    const response = await guardedGeminiGenerate("internal", {
      model: getLightModel(),
      contents: `Analiza este mensaje de cliente de turismo en Costa Rica: "${rawMessage}". Extrae intenci\xF3n y datos estructurados.`,
      config: {
        systemInstruction: "Eres el Agente Triage. Devuelve un JSON con: intent (booking_inquiry, pricing, modification, cancellation, support), confidence (n\xFAmero 0 a 1), extractedData: { tourName, passengers, targetDate, language, budget, contact }",
        responseMimeType: "application/json"
      }
    }, { client: ai, containsPii: true });
    return JSON.parse(response.text || "{}");
  } catch {
    const lower = rawMessage.toLowerCase();
    const isBooking = lower.includes("reserv") || lower.includes("book");
    const isPrice = lower.includes("precio") || lower.includes("cost") || lower.includes("cuanto");
    return {
      intent: isBooking ? "booking_inquiry" : isPrice ? "pricing" : "general_inquiry",
      confidence: 0.9,
      extractedData: {
        raw: rawMessage,
        language: rawMessage.match(/[a-zA-Z]/) ? "es" : "es"
      }
    };
  }
}
